nextflow_process {

    name "Test Process AMULETY_ANTIBERTA2"
    script "../main.nf"
    process "AMULETY_ANTIBERTA2"

    tag "modules"
    tag "modules_nfcore"
    tag "amulety"
    tag "amulety/antiberta2"

    test("deprecated") {

        when {
            process {
                """
                input[0] = [ [ id:'test' ], file('tsv') ]
                input[1] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.failed },
                { assert process.errorReport.contains("WARNING: This module has been deprecated. Please use nf-core/modules/amulety/embed instead") }
            )
        }
    }
}
